// Literal port of the team's Casa3DSDK (module interaction/state). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installInteractionState(K: Kernel, shared: Shared): void {
  const { THREE, cfg, colliderChanged, invalidateShadow, invalidate, UV_SCALE, applyPart, texture } = K;
  const ivRoomEffective = (...a: any[]): any => K.ivRoomEffective(...a);
  const ivRoomLight = (...a: any[]): any => K.ivRoomLight(...a);
  // ---------------- 60 interaction (moving parts, doors, lights, object collision) ----------------
  // ===== interaction: free flight, object collision, handles, switches, curtains, gates and cabinets =====
  // Moving pieces are drawn as "ix:..." groups (one mesh per material) and then wrapped in two nodes:
  // "outer" at the hinge/axis (item position + rotation) and "inner", which receives the animation in the item's frame.
  shared.partState = new Map();
   // piece name / 'light:living' -> target; reset together with DOOR_STATE when the model changes
  const newInteractiveState = () => ({ defs: new Map(), items: [], pieces: [], lights: new Map(), litRooms: new Set(), objs: [], anim: new Set(), msg: null, target: null });
  shared.inter = newInteractiveState();
  const MESSAGE_MS = 2200;
  UV_SCALE.doorWood = 1.0;
  UV_SCALE.doorPaint = 1.0;
  function createInteractiveMaterials(mats) {
    const rg = (s => () => (s = (s * 16807) % 2147483647) / 2147483647)(777);
    const wood = texture(256, (g, n) => { // soft vertical grain, light tone to take the vertex colour
      g.fillStyle = '#e8dccb'; g.fillRect(0, 0, n, n);
      for (let i = 0; i < 90; i++) { const x = rg() * n, w = 1 + rg() * 5, v = 150 + rg() * 90 | 0; g.fillStyle = `rgba(${v - 40},${v - 70},${v - 110},${0.10 + rg() * 0.16})`; g.fillRect(x, 0, w, n); }
      for (let i = 0; i < 400; i++) { const x = rg() * n, y = rg() * n; g.fillStyle = `rgba(90,60,30,${0.05 + rg() * 0.1})`; g.fillRect(x, y, 1, 8 + rg() * 30); }
      for (let k = 0; k < 2; k++) { const x = 30 + rg() * 190, y = 30 + rg() * 190; g.strokeStyle = 'rgba(70,45,20,0.25)'; for (let r = 2; r < 9; r += 2) { g.beginPath(); g.ellipse(x, y, r * 0.8, r * 2.2, 0, 0, 6.3); g.stroke(); } }
      g.fillStyle = 'rgba(60,40,20,0.22)'; g.fillRect(0, 0, 2, n); g.fillRect(n - 2, 0, 2, n);
    });
    const paint = texture(256, (g, n) => { // matte paint with a slight roller texture and scratches
      g.fillStyle = '#f4f3f0'; g.fillRect(0, 0, n, n);
      for (let i = 0; i < 2600; i++) { const v = 220 + rg() * 35 | 0; g.fillStyle = `rgba(${v},${v},${v},0.55)`; g.fillRect(rg() * n, rg() * n, 1 + rg() * 3, 2 + rg() * 8); }
      for (let i = 0; i < 40; i++) { g.strokeStyle = `rgba(0,0,0,${0.03 + rg() * 0.05})`; g.beginPath(); const x = rg() * n, y = rg() * n; g.moveTo(x, y); g.lineTo(x + (rg() - 0.5) * 24, y + rg() * 30); g.stroke(); }
    });
    mats.doorWood = new THREE.MeshLambertMaterial({ vertexColors: true, map: wood });
    mats.doorPaint = new THREE.MeshLambertMaterial({ vertexColors: true, map: paint });
    mats.off = new THREE.MeshBasicMaterial({ vertexColors: true, color: 0x8a8780 });
  }
  // ---------- utilities ----------
  const _EY = new THREE.Vector3(0, 1, 0), _UM3 = new THREE.Vector3(1, 1, 1);
  const hudMessage = text => { shared.inter.msg = { text, until: performance.now() + MESSAGE_MS }; if (cfg.onMessage) cfg.onMessage(text); };
  function definePiece(name, def) { def.name = name; def.meshes = []; def.t = def.target = shared.partState.has(name) ? shared.partState.get(name) : (def.t0 || 0); shared.inter.defs.set(name, def); shared.inter.pieces.push(def); return def; }
  const localOf = (M, lx, lz) => { const c = Math.cos(M.ry), s = Math.sin(M.ry); return [M.x + lx * c + lz * s, M.z - lx * s + lz * c]; };
  function visibleChain(o) { for (let n = o; n; n = n.parent) if (!n.visible) return false; return true; }
  function assembleInteractive(gs) {
    for (const [name, def] of shared.inter.defs) {
      const g = gs[name]; if (!g) continue; delete gs[name];
      const outer = new THREE.Group(); outer.position.set(...def.pivot); outer.rotation.y = def.ry || 0; outer.updateMatrix();
      const inv = new THREE.Matrix4().compose(new THREE.Vector3(...def.pivot), new THREE.Quaternion().setFromAxisAngle(_EY, def.ry || 0), _UM3).invert();
      g.traverse(o => { if (o.isMesh) { o.geometry.applyMatrix4(inv); o.userData.piece = def; def.meshes.push(o); } });
      outer.add(g); def.outer = outer; def.inner = g;
      const parent = def.leaf ? def.leaf.gs[def.k] : (gs[def.parent] || (gs[def.parent] = new THREE.Group()));
      if (parent) parent.add(outer);
      if (def.roomId) { if (!shared.inter.lights.has(def.roomId)) shared.inter.lights.set(def.roomId, []); shared.inter.lights.get(def.roomId).push(def); }
      applyPiece(def);
    }
    for (const roomId of shared.inter.litRooms) applyLight(roomId);
    shared.inter.defs.forEach(d => { if (d.col) d.col.off = d.t > 0.5; });
  }
  function applyPiece(p) {
    const n = p.inner; if (!n) return;
    switch (p.kind) {
      case 'swing': n.rotation.y = p.sgn * p.t * p.angle; break;
      case 'drawer': n.position.z = p.t * p.travel; break;
      case 'curtain': n.scale.x = 1 + (p.k - 1) * p.t; break;
      case 'gate_swing': n.rotation.y = p.t * p.angle; break;
      case 'gate_tilting': n.rotation.x = p.t * p.angle; break;
      case 'gate_sliding': n.position.x = p.t * p.travel; break;
      case 'light_switch': n.rotation[p.axis] = (p.t * 2 - 1) * 0.42 * p.sgn; break;
      case 'handle': n.rotation[p.axis] = p.t * p.angle; break;
      case 'part': applyPart(n, p.t); return; // moving part of the part:<id>:<n> contract (mailbox): pose by userData.opens
    }
    n.updateMatrix();
  }
  const DURATION = { swing: 0.55, drawer: 0.4, curtain: 0.9, gate_swing: 0.9, gate_tilt: 1.4, gate_slide: 1.6, lightSwitch: 0.12, part: 0.4 };
  function animateInteractive(dt) {
    if (!shared.inter.anim.size) return;
    for (const p of shared.inter.anim) {
      const step = dt / (DURATION[p.kind] || 0.5), d = p.target - p.t;
      p.t = Math.abs(d) <= step ? p.target : p.t + Math.sign(d) * step; applyPiece(p);
      if (p.col && p.col.off !== (p.target > 0.5)) { p.col.off = p.target > 0.5; colliderChanged(p.col); } // the gate stops blocking as soon as it starts to open
      if (p.t === p.target) shared.inter.anim.delete(p);
    }
    invalidateShadow();
  }
  function togglePiece(p) { p.target = p.target > 0.5 ? 0 : 1; shared.partState.set(p.name, p.target); if (p.col && p.col.off !== (p.target > 0.5)) { p.col.off = p.target > 0.5; colliderChanged(p.col); } shared.inter.anim.add(p); }
  const lightBase = roomId => (roomId == null ? true : (shared.partState.has('light:' + roomId) ? !!shared.partState.get('light:' + roomId) : !!shared.ctx.night));
  const lightOn = roomId => { const S = roomId != null && shared.ctx.iv && shared.ctx.iv.roomStates.get(roomId); return S ? S.ef : lightBase(roomId); };
   // with cfg.interactives the room is lit when some kit lamp is on and powered
  function applyLight(roomId) {
    const on = lightOn(roomId);
    for (const d of shared.inter.lights.get(roomId) || []) for (const m of d.meshes) if (m.name.endsWith('/emissive')) m.material = on ? shared.mats.emissive : shared.mats.off;
    const sw = shared.inter.defs.get('ix:int:' + roomId); if (sw) { sw.target = on ? 1 : 0; if (sw.t !== sw.target) shared.inter.anim.add(sw); }
    invalidate();
  }
  function toggleLight(roomId) {
    const S = shared.ctx.iv && shared.ctx.iv.roomStates.get(roomId);
    if (S) { ivRoomLight(shared.ctx.iv, roomId, !S.ef); const ef = ivRoomEffective(shared.ctx.iv, S); if (ef !== S.ef) { S.ef = ef; applyLight(roomId); if (cfg.onLight) cfg.onLight(roomId, ef); } return; }
    shared.partState.set('light:' + roomId, !lightOn(roomId)); applyLight(roomId); if (cfg.onLight) cfg.onLight(roomId, lightOn(roomId));
  }
  Object.assign(K, { newInteractiveState, MESSAGE_MS, createInteractiveMaterials, _EY, _UM3, hudMessage, definePiece, localOf, visibleChain, assembleInteractive, applyPiece, DURATION, animateInteractive, togglePiece, lightBase, lightOn, applyLight, toggleLight });
}
